@Test
@Ignore
public void testDuplicatesIgnored() {
    final ProvenanceEventRepository mockRepo = Mockito.mock(ProvenanceEventRepository.class);
    final StandardProvenanceReporter reporter = new StandardProvenanceReporter(null, "1234", "TestProc", mockRepo, null);
    final List<FlowFile> parents = new ArrayList<>();
    for (int i = 0; i < 10; i++) {
        final FlowFile ff = new StandardFlowFileRecord.Builder().id(i).addAttribute("uuid", String.valueOf(i)).build();
        parents.add(ff);
    }
    final FlowFile flowFile = new StandardFlowFileRecord.Builder().id(10L).addAttribute("uuid", "10").build();
    reporter.fork(flowFile, parents);
    reporter.fork(flowFile, parents);
    final Set<ProvenanceEventRecord> records = reporter.getEvents();
    // 1 for each parent in the spawn and 1 for the spawn itself
    assertEquals(11, records.size());
    final FlowFile firstParent = parents.get(0);
    parents.clear();
    parents.add(firstParent);
    reporter.fork(flowFile, parents);
    // 1 more emitted for the spawn event containing the child but not for the parent because that one has already been emitted
    assertEquals(12, reporter.getEvents().size());
}

@Test
public void testRedirects() throws IOException {
    System.setProperty(NiFiProperties.PROPERTIES_FILE_PATH, "src/test/resources/conf/nifi.properties");
    final NiFiProperties props = NiFiProperties.getInstance();
    props.setProperty(VolatileContentRepository.MAX_SIZE_PROPERTY, "10 MB");
    final VolatileContentRepository contentRepo = new VolatileContentRepository();
    contentRepo.initialize(claimManager);
    final ContentClaim claim = contentRepo.create(true);
    final OutputStream out = contentRepo.write(claim);
    final byte[] oneK = new byte[1024];
    Arrays.fill(oneK, (byte) 55);
    // Write 10 MB to the repo
    for (int i = 0; i < 10240; i++) {
        out.write(oneK);
    }
    try {
        out.write(1);
        Assert.fail("Expected to be out of space on content repo");
    } catch (final IOException e) {
    }
    try {
        out.write(1);
        Assert.fail("Expected to be out of space on content repo");
    } catch (final IOException e) {
    }
    final ContentRepository mockRepo = Mockito.mock(ContentRepository.class);
    contentRepo.setBackupRepository(mockRepo);
    final ResourceClaim resourceClaim = claimManager.newResourceClaim("container", "section", "1000", true);
    final ContentClaim contentClaim = new StandardContentClaim(resourceClaim, 0L);
    Mockito.when(mockRepo.create(Matchers.anyBoolean())).thenReturn(contentClaim);
    final ByteArrayOutputStream overflowStream = new ByteArrayOutputStream();
    Mockito.when(mockRepo.write(Matchers.any(ContentClaim.class))).thenReturn(overflowStream);
    out.write(10);
    assertEquals(1024 * 1024 * 10 + 1, overflowStream.size());
    final byte[] overflowBuffer = overflowStream.toByteArray();
    assertEquals(55, overflowBuffer[0]);
    for (int i = 0; i < overflowBuffer.length; i++) {
        if (i == overflowBuffer.length - 1) {
            assertEquals(10, overflowBuffer[i]);
        } else {
            assertEquals(55, overflowBuffer[i]);
        }
    }
}

